        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and grid[0][c] != bg:
                guide = ('col', c, grid[0][c])
                break
    if guide is None:
        return [row[:] for row in grid]

    axis, pos, guide_color = guide
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, guide_color)]
    if not obj:
        return [row[:] for row in grid]

    # Slide the object toward the guide until its nearest edge touches it.
    if axis == 'col':
        cols = [c for r, c, v in obj]
        if min(cols) > pos:
            delta = pos + 1 - min(cols)
            direction = 1
        else:
            delta = pos - 1 - max(cols)
            direction = -1
        moved = [(r, c + delta, v) for r, c, v in obj]
        edge = max(c for r, c, v in moved) if direction == 1 else min(c for r, c, v in moved)
        marker = edge + direction
